"use client";

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "./collapsible";
import {
  SidebarGroup,
  SidebarMenu,
  SidebarNavLinkItem,
  SidebarSectionHeader,
} from "./sidebar";
import { ChevronRightIcon } from "lucide-react";
import { useState, type ReactNode } from "react";

export type SidebarFavoriteItem = {
  id: string;
  href: string;
  label: string;
  icon?: ReactNode;
  isActive?: boolean;
};

export function SidebarFavoritesGroup({
  items,
  title = "Favorites",
  defaultOpen = true,
}: Readonly<{
  items: SidebarFavoriteItem[];
  title?: string;
  defaultOpen?: boolean;
}>) {
  const [open, setOpen] = useState(defaultOpen);

  if (items.length === 0) {
    return null;
  }

  return (
    <SidebarGroup>
      <Collapsible onOpenChange={setOpen} open={open}>
        <CollapsibleTrigger asChild>
          <SidebarSectionHeader
            action={
              <ChevronRightIcon
                className={`h-4 w-4 transition-transform ${open ? "rotate-90" : ""}`}
              />
            }
            title={title}
          />
        </CollapsibleTrigger>
        <CollapsibleContent>
          <SidebarMenu>
            {items.map((item) => (
              <SidebarNavLinkItem
                href={item.href}
                icon={item.icon}
                isActive={item.isActive}
                key={item.id}
                title={item.label}
              />
            ))}
          </SidebarMenu>
        </CollapsibleContent>
      </Collapsible>
    </SidebarGroup>
  );
}
